def spiral_walk(grid: list[list[int]]) -> list[int]:
    """Return the elements of a rectangular grid in clockwise spiral order, starting at the
    top-left corner and moving right first."""
    result = []
    if not grid or not grid[0]:
        return result
    top, bottom, left, right = 0, len(grid) - 1, 0, len(grid[0]) - 1
    while top <= bottom and left <= right:
        for c in range(left, right + 1):
            result.append(grid[top][c])
        for r in range(top + 1, bottom + 1):
            result.append(grid[r][right])
        if top < bottom:
            for c in range(right - 1, left - 1, -1):
                result.append(grid[bottom][c])
        if left < right:
            for r in range(bottom - 1, top, -1):
                result.append(grid[r][left])
        top, bottom, left, right = top + 1, bottom - 1, left + 1, right - 1
    return result

def merge_ranges(ranges: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """Merge overlapping or touching closed integer ranges (start <= end).

    Ranges (1, 3) and (4, 6) touch because no integer lies between them, so they merge into
    (1, 6). Return the merged ranges sorted by start.
    """
    merged = []
    for start, end in sorted(ranges):
        if merged and start <= merged[-1][1] + 1:
            last_start, last_end = merged[-1]
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))
    return merged

