def roman_to_int(numeral: str) -> int:
    """Convert a valid Roman numeral (I, V, X, L, C, D, M with subtractive notation such as
    IV and CM) to an integer."""
    values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    total = 0
    for i, ch in enumerate(numeral):
        value = values[ch]
        if i + 1 < len(numeral) and values[numeral[i + 1]] > value:
            total -= value
        else:
            total += value
    return total

def to_base(value: int, base: int) -> str:
    """Render an integer in the given base (2..36) using digits 0-9 then lowercase a-z.

    Negative numbers get a leading "-". Raise ValueError for an unsupported base.
    """
    if not 2 <= base <= 36:
        raise ValueError("base must be between 2 and 36")
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    if value == 0:
        return "0"
    sign = "-" if value < 0 else ""
    value = abs(value)
    out = []
    while value:
        value, rem = divmod(value, base)
        out.append(digits[rem])
    return sign + "".join(reversed(out))

