def caesar_shift(text: str, shift: int) -> str:
    """Shift ASCII letters by shift positions, wrapping within the alphabet and preserving
    case. Non-letters are unchanged; shift may be negative or larger than 26."""
    out = []
    for ch in text:
        if "a" <= ch <= "z":
            out.append(chr((ord(ch) - 97 + shift) % 26 + 97))
        elif "A" <= ch <= "Z":
            out.append(chr((ord(ch) - 65 + shift) % 26 + 65))
        else:
            out.append(ch)
    return "".join(out)

