def shortest_paths(graph: dict[str, dict[str, int]], source: str) -> dict[str, int]:
    """Return the minimum total edge weight from source to every reachable node.

    graph maps a node to {neighbour: non-negative weight}. Nodes that only appear as
    neighbours are still nodes. Unreachable nodes are omitted; the source maps to 0.
    """
    import heapq

    dist = {source: 0}
    heap = [(0, source)]
    while heap:
        d, node = heapq.heappop(heap)
        if d > dist.get(node, float("inf")):
            continue
        for neighbour, weight in graph.get(node, {}).items():
            candidate = d + weight
            if candidate < dist.get(neighbour, float("inf")):
                dist[neighbour] = candidate
                heapq.heappush(heap, (candidate, neighbour))
    return dist

def build_order(deps: dict[str, list[str]]) -> list[str]:
    """Return an order in which every item appears after all of its dependencies.

    deps maps an item to the items it depends on; dependencies that are not keys are items
    with no dependencies. When several items are ready at once pick the alphabetically
    smallest, so the answer is unique. Raise ValueError if there is a cycle.
    """
    import heapq

    nodes = set(deps)
    for requirements in deps.values():
        nodes.update(requirements)
    indegree = {node: 0 for node in nodes}
    dependents = {node: [] for node in nodes}
    for item, requirements in deps.items():
        for req in set(requirements):
            indegree[item] += 1
            dependents[req].append(item)
    ready = [node for node, deg in indegree.items() if deg == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(nodes):
        raise ValueError("dependency cycle detected")
    return order

