def change_ways(amount: int, coins: list[int]) -> int:
    """Count the distinct multisets of coins (unlimited supply of each denomination) that
    sum to amount. The order of coins does not matter; amount 0 has exactly one way."""
    ways = [1] + [0] * amount
    for coin in sorted(set(coins)):
        for total in range(coin, amount + 1):
            ways[total] += ways[total - coin]
    return ways[amount]

def window_maxima(values: list[int], width: int) -> list[int]:
    """Return the maximum of every contiguous window of the given width, left to right.

    Return an empty list when width exceeds len(values); raise ValueError if width < 1.
    The solution should run in linear time.
    """
    from collections import deque

    if width < 1:
        raise ValueError("width must be >= 1")
    window = deque()
    out = []
    for i, v in enumerate(values):
        while window and values[window[-1]] <= v:
            window.pop()
        window.append(i)
        if window[0] <= i - width:
            window.popleft()
        if i >= width - 1:
            out.append(values[window[0]])
    return out

