def primes_below(limit: int) -> list[int]:
    """Return all primes strictly less than limit in increasing order."""
    if limit < 3:
        return []
    sieve = bytearray([1]) * limit
    sieve[0] = sieve[1] = 0
    for p in range(2, int(limit ** 0.5) + 1):
        if sieve[p]:
            sieve[p * p :: p] = bytearray(len(range(p * p, limit, p)))
    return [i for i, flag in enumerate(sieve) if flag]

def wrap_words(text: str, width: int) -> list[str]:
    """Greedily wrap the words of text into lines of at most width characters.

    Words are separated by whitespace and joined by single spaces. A word longer than width
    gets a line of its own (it is not split). Empty text gives an empty list.
    """
    lines = []
    current = ""
    for word in text.split():
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines

def running_medians(values: list[int]) -> list[float]:
    """After each value of the stream is read, record the median of everything read so far.

    The median of an even count is the mean of the two middle values. Return the medians as
    floats. Aim for O(n log n) overall.
    """
    import heapq

    low = []
    high = []
    out = []
    for v in values:
        if low and v > -low[0]:
            heapq.heappush(high, v)
        else:
            heapq.heappush(low, -v)
        if len(low) > len(high) + 1:
            heapq.heappush(high, -heapq.heappop(low))
        elif len(high) > len(low):
            heapq.heappush(low, -heapq.heappop(high))
        if len(low) > len(high):
            out.append(float(-low[0]))
        else:
            out.append((-low[0] + high[0]) / 2)
    return out

