def is_ipv4(address: str) -> bool:
    """Return True for a dotted-quad IPv4 address: exactly four decimal parts 0-255, no
    signs, no whitespace and no leading zeros (except the single digit "0")."""
    parts = address.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part or not part.isascii() or not part.isdigit():
            return False
        if len(part) > 1 and part[0] == "0":
            return False
        if int(part) > 255:
            return False
    return True

def anagram_groups(words: list[str]) -> list[list[str]]:
    """Group words that are anagrams of each other.

    Each group is sorted alphabetically and groups are ordered by their first word.
    Comparison is case-sensitive and duplicate words are kept.
    """
    groups = {}
    for word in words:
        groups.setdefault("".join(sorted(word)), []).append(word)
    return sorted((sorted(group) for group in groups.values()), key=lambda g: g[0])

def apply_ledger(balance: int, entries: list[tuple[str, str, int]]) -> tuple[int, list[str]]:
    """Apply ledger entries to an account balance.

    Each entry is (entry_id, kind, amount) where kind is "deposit" or "withdraw" and amount
    is positive. A withdrawal that would make the balance negative is rejected and skipped.
    Return (final_balance, rejected_entry_ids) with rejected ids in input order. Raise
    ValueError for an unknown kind or a non-positive amount.
    """
    rejected = []
    for entry_id, kind, amount in entries:
        if amount <= 0:
            raise ValueError(f"entry {entry_id}: amount must be positive")
        if kind == "deposit":
            balance += amount
        elif kind == "withdraw":
            if amount > balance:
                rejected.append(entry_id)
            else:
                balance -= amount
        else:
            raise ValueError(f"entry {entry_id}: unknown kind {kind!r}")
    return balance, rejected

