def eval_postfix(expression: str) -> int:
    """Evaluate a whitespace-separated postfix (reverse Polish) integer expression.

    Supported operators are +, -, * and / where / is integer division truncating toward
    zero. Operands may be negative (e.g. "-3"). Raise ValueError for malformed input.
    """
    stack = []
    for token in expression.split():
        if token in ("+", "-", "*", "/"):
            if len(stack) < 2:
                raise ValueError("not enough operands")
            right = stack.pop()
            left = stack.pop()
            if token == "+":
                stack.append(left + right)
            elif token == "-":
                stack.append(left - right)
            elif token == "*":
                stack.append(left * right)
            else:
                if right == 0:
                    raise ValueError("division by zero")
                quotient = abs(left) // abs(right)
                stack.append(quotient if (left >= 0) == (right >= 0) else -quotient)
        else:
            try:
                stack.append(int(token))
            except ValueError:
                raise ValueError(f"bad token {token!r}") from None
    if len(stack) != 1:
        raise ValueError("malformed expression")
    return stack[0]

