def insert_position(sorted_values: list[int], target: int) -> int:
    """Return the leftmost index at which target could be inserted into the ascending list
    sorted_values while keeping it sorted. Use binary search (O(log n))."""
    lo, hi = 0, len(sorted_values)
    while lo < hi:
        mid = (lo + hi) // 2
        if sorted_values[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

